using System;
using System.Linq;
using System.Collections.Generic;
using Newtonsoft.Json.Linq;
namespace LastRail.Battle {
 // Owned position/path observations driven by native tick. No second clock or HP cache.
 internal sealed class BOrdinarySpatialOwner {
  sealed class State {internal string Id,Phase,Target,ForcedTarget;internal int Slot,Side,RepathSlot=-1;internal long Generation,PathRevision,Started;internal BMmPoint TargetObserved;internal BMmPoint Position;internal BMmPoint[] Route;internal bool Ready;internal State Copy(){var s=(State)MemberwiseClone();s.Route=Route?.ToArray();return s;}}
  readonly BOrdinarySpatialGeometry geometry;readonly BDirectAttackInput input;readonly BBoardingRoster roster;readonly Dictionary<string,long> speeds;readonly Dictionary<string,State> states=new Dictionary<string,State>(StringComparer.Ordinal);long tick=-1,revision;
  sealed class OperatorPose {internal string Id;internal int Slot,DestinationSlot;internal BMmPoint Position;internal BMmPoint[] Path;internal long Started,Revision,Generation;internal OperatorPose Copy(){var p=(OperatorPose)MemberwiseClone();p.Path=Path?.ToArray();return p;}}
  readonly Dictionary<string,OperatorPose> operators=new Dictionary<string,OperatorPose>();
#if !LASTRAIL_ORDINARY_CORE
  internal BOrdinarySpatialOwner(BOrdinaryGeometryBinding source,LastRail.Run.BScoutGunnerNodeSnapshot original):this(new BLegacySpatialGeometry(source),original){}
#endif
  internal BOrdinarySpatialOwner(BOrdinarySpatialGeometry source,LastRail.Run.BScoutGunnerNodeSnapshot original):this(source,original,BBoardingRoster.FromNative(source.Input)){}
  internal BOrdinarySpatialOwner(BOrdinarySpatialGeometry source,LastRail.Run.BScoutGunnerNodeSnapshot original,BBoardingRoster roster){geometry=source;input=source.Input;this.roster=roster;speeds=((JArray)original.Capture()["definition"]["types"]).ToDictionary(t=>(string)t["definitionId"],t=>(long)t["spatial"]["movementSpeedMmPerSecond"]);}
  BOrdinarySpatialOwner(BOrdinarySpatialOwner source){geometry=source.geometry;input=source.input;roster=source.roster;speeds=source.speeds;tick=source.tick;revision=source.revision;foreach(var pair in source.states)states.Add(pair.Key,pair.Value.Copy());foreach(var pair in source.operators)operators.Add(pair.Key,pair.Value.Copy());}
  internal BOrdinarySpatialOwner Clone()=>new BOrdinarySpatialOwner(this);internal string Hash=>geometry.Hash;
  internal void Begin(long actualTick){BuffWire.Need(actualTick>=tick,"b_spatial_clock_reversed");if(actualTick!=tick){tick=actualTick;revision++;}}
  internal void ObserveOperators(IBBoardingActors native){Begin(native.Tick);foreach(var e in roster.Entities.Values.Where(e=>e.Kind=="OPERATOR")){if(!operators.TryGetValue(e.Id,out var pose)){pose=new OperatorPose{Id=e.Id,Slot=e.Slot,DestinationSlot=e.Slot,Position=geometry.EntityAnchor(e.Id,e.Slot,"actorMm")};operators.Add(e.Id,pose);}pose.Generation=native.ProjectileTargetGeneration(e.Id);if(pose.Path==null||native.Hp(e.Id)==0)continue;long distance=checked((long)((System.Numerics.BigInteger)(tick-pose.Started)*roster.StepMicroseconds*geometry.OperatorSpeed(e.Id)/1000000));pose.Position=BOrdinaryGeometrySnapshot.OnPath(pose.Path,distance);pose.Slot=geometry.RoofSlot(pose.Position,pose.Slot);}}
  internal void Move(string actor,int slot,BMmPoint localPoint,string hash,IBBoardingActors native){BuffWire.Need(hash==geometry.Hash&&slot>=0&&slot<geometry.Count&&roster.Entities.TryGetValue(actor,out var e)&&e.Kind=="OPERATOR"&&native.Hp(actor)>0&&geometry.ContainsLocalRoof(slot,localPoint),"b_geometry_move_source");geometry.OperatorSpeed(actor);ObserveOperators(native);var pose=operators[actor];var path=geometry.Route(pose.Position,pose.Slot,slot,geometry.World(slot,localPoint));BuffWire.Need(path!=null&&Enumerable.Range(1,path.Length-1).All(i=>geometry.Los(path[i-1],path[i])),"b_geometry_move_unreachable");pose.Path=path;pose.Started=tick;pose.DestinationSlot=slot;pose.Revision++;}
  internal long OperatorMovementRevision(string actor)=>operators.TryGetValue(actor,out var pose)?pose.Revision:throw new ArgumentException("Unknown observed operator");
  internal bool CancelOperatorMove(string actor,long expectedRevision,string hash,IBBoardingActors native){
   BuffWire.Need(hash==geometry.Hash&&expectedRevision>0&&roster.Entities.TryGetValue(actor,out var entity)&&entity.Kind=="OPERATOR","b_geometry_cancel_source");
   if(!operators.TryGetValue(actor,out var pose)||pose.Revision!=expectedRevision||pose.Path==null)return false;
   // Observe the current native position before dropping only this request's path.
   ObserveOperators(native);pose.Path=null;pose.DestinationSlot=pose.Slot;pose.Revision++;return true;
  }
  long Speed(string id)=>speeds[roster.Entities[id].Definition];
  long Travelled(string id,long elapsed)=>checked((long)((System.Numerics.BigInteger)Math.Max(0,elapsed)*roster.StepMicroseconds*Speed(id)/1000000));
  internal long PhaseTicks(string id,int slot,int side,string phase,long nominal){var path=geometry.WorldPath(slot,side,phase=="Approach"?"approachMm":"climbMm");long length=BOrdinaryGeometrySnapshot.Length(path);var denominator=(System.Numerics.BigInteger)Speed(id)*roster.StepMicroseconds;return Math.Max(nominal,checked((long)(((System.Numerics.BigInteger)length*1000000+denominator-1)/denominator)));}
  internal bool Ready(string id)=>states.TryGetValue(id,out var s)&&s.Ready;
  internal int Slot(string id)=>states.TryGetValue(id,out var s)?s.Slot:operators.TryGetValue(id,out var p)?p.Slot:roster.Entities[id].Slot;
  internal string Target(string id)=>states.TryGetValue(id,out var s)?s.Target:null;
  internal bool HasTauntChange(IBBoardingActors native)=>states.Values.Any(s=>s.Phase=="Rooftop"&&s.ForcedTarget!=(native as IBBoardingTauntTargets)?.ForcedTarget(s.Id));
  internal bool Repath(string id,int side,int destination,IBBoardingActors native){if(!states.TryGetValue(id,out var s)||destination<0)return false;Begin(native.Tick);if(s.RepathSlot!=destination){if(s.RepathSlot>=0&&s.Route!=null)s.Position=BOrdinaryGeometrySnapshot.OnPath(s.Route,Travelled(id,tick-s.Started));var route=geometry.GroundRoute(s.Position,s.Slot,destination,side);if(route==null||Enumerable.Range(1,route.Length-1).Any(i=>!geometry.Los(route[i-1],route[i])))return false;s.Route=route;s.RepathSlot=destination;s.Started=tick;s.PathRevision++;}s.Position=BOrdinaryGeometrySnapshot.OnPath(s.Route,Travelled(id,tick-s.Started));if(!JToken.DeepEquals(s.Position.Capture(),s.Route.Last().Capture()))return false;s.Slot=destination;s.RepathSlot=-1;s.Route=null;return true;}
  internal bool Connected(int a,int b)=>geometry.Connected(a,b);
  internal void Observe(string id,int slot,int side,string phase,long phaseStarted,long generation,IBBoardingActors native){Begin(native.Tick);if(!states.TryGetValue(id,out var s)){s=new State{Id=id,Slot=slot,Side=side,Position=geometry.WorldPath(slot,side,"approachMm").First()};states.Add(id,s);}s.Generation=generation;s.Ready=false;
   bool entering=s.Phase!=phase;var previous=s.Phase;s.Phase=phase;s.Side=side;
   if(phase=="Entrance"){s.Position=geometry.WorldPath(slot,side,"approachMm").First();s.Slot=slot;}
   else if(phase=="Approach"||phase=="WaitingSocket"){s.Position=BOrdinaryGeometrySnapshot.OnPath(geometry.WorldPath(slot,side,"approachMm"),phase=="WaitingSocket"?long.MaxValue:Travelled(id,native.Tick-phaseStarted));s.Slot=slot;}
   else if(phase=="Attached"){s.Position=geometry.WorldPath(slot,side,"climbMm").First();s.Slot=slot;}
   else if(phase=="Climbing"){s.Position=BOrdinaryGeometrySnapshot.OnPath(geometry.WorldPath(slot,side,"climbMm"),Travelled(id,native.Tick-phaseStarted));s.Slot=slot;}
   else if(phase=="GeometryPending"&&s.RepathSlot>=0&&s.Route!=null)s.Position=BOrdinaryGeometrySnapshot.OnPath(s.Route,Travelled(id,tick-s.Started));
   else if(phase=="Rooftop"){
    if(entering){s.Position=geometry.WorldPath(slot,side,"climbMm").Last();s.Slot=slot;s.Route=null;s.Target=null;}
    if(s.Route!=null)s.Position=BOrdinaryGeometrySnapshot.OnPath(s.Route,Travelled(id,native.Tick-s.Started));s.Slot=geometry.RoofSlot(s.Position,s.Slot);
    string forced=(native as IBBoardingTauntTargets)?.ForcedTarget(id);
    if(s.Target==null||s.ForcedTarget!=forced||native.Hp(s.Target)==0||!JToken.DeepEquals(s.TargetObserved.Capture(),Position(s.Target).Capture())){s.ForcedTarget=forced;SelectRoute(s,native);}
    if(s.Route!=null){s.Position=BOrdinaryGeometrySnapshot.OnPath(s.Route,Travelled(id,native.Tick-s.Started));s.Slot=geometry.RoofSlot(s.Position,s.Slot);s.Ready=JToken.DeepEquals(s.Position.Capture(),s.Route.Last().Capture())&&s.Target!=null&&native.Hp(s.Target)>0;}
   }
  }
  void SelectRoute(State s,IBBoardingActors native){bool gunner=roster.Entities[s.Id].Definition=="enemy_spike_cart_gunner";var options=new List<(string target,BMmPoint goal,long distance,BMmPoint[] path)>();foreach(var entity in roster.Entities.Values.Where(e=>e.Kind=="OPERATOR"&&native.Hp(e.Id)>0&&(s.ForcedTarget==null||s.ForcedTarget==e.Id))){
    if(!geometry.Connected(s.Slot,Slot(entity.Id)))continue;var target=ReferencePoint(entity.Id,"hitMm");var anchors=gunner?Enumerable.Range(0,geometry.Count).Where(i=>geometry.Connected(s.Slot,i)).SelectMany(i=>geometry.GunnerPoints(i).Select(a=>(slot:i,point:a))):new[]{(slot:Slot(entity.Id),point:geometry.ScoutGoal(Slot(entity.Id),Position(entity.Id)))};
    foreach(var a in anchors){var fire=OffsetPoint(a.point,a.slot,"fireMm",s.Id);long distance=BMmPoint.Distance(fire,target);if(distance>(gunner?24000:1800)||!geometry.Los(fire,target))continue;var path=geometry.Route(s.Position,s.Slot,a.slot,a.point);if(path==null||Enumerable.Range(1,path.Length-1).Any(i=>!geometry.Los(path[i-1],path[i])))continue;options.Add((entity.Id,a.point,distance,path));}}
   var chosen=gunner?options.OrderByDescending(x=>x.distance).ThenBy(x=>x.target,StringComparer.Ordinal).FirstOrDefault():options.OrderBy(x=>BOrdinaryGeometrySnapshot.Length(x.path)).ThenBy(x=>x.target,StringComparer.Ordinal).FirstOrDefault();s.Target=chosen.target;s.TargetObserved=s.Target==null?default:Position(s.Target);s.Route=chosen.path;s.Started=tick;s.PathRevision++;
  }
  internal KyleTauntPolicy.Candidate ObserveTaunt(string caster,string enemy,long generation,int order,bool immune){
   var body=ReferencePoint(caster,"hitMm");var hit=ReferencePoint(enemy,"hitMm");string target=Target(enemy);
   bool threat=Slot(caster)==Slot(enemy)||target!=null&&Slot(target)==Slot(caster);
   return new KyleTauntPolicy.Candidate(enemy,generation,BMmPoint.Squared(body,hit),order,threat,geometry.Los(body,hit),immune);
  }
  internal bool Protection(string actor,string target){int a=Slot(actor),b=Slot(target);return geometry.Connected(a,b)&&BCombatRoleRanges.For(roster.Entities[actor].Definition).InterceptionIncludesSlot(a,b,geometry.Count);}
  internal BMmPoint Position(string id){if(roster.Entities[id].Kind=="LOCAL_ENEMY"){BuffWire.Need(states.ContainsKey(id),"b_spatial_entity_not_observed");return states[id].Position;}return operators.TryGetValue(id,out var pose)?pose.Position:geometry.EntityAnchor(id,roster.Entities[id].Slot,"actorMm");}
  BMmPoint ReferencePoint(string id,string name)=>OffsetPoint(Position(id),Slot(id),name,id);
  BMmPoint OffsetPoint(BMmPoint position,int slot,string name,string id){var a=geometry.EntityAnchor(id,slot,"actorMm");var b=geometry.EntityAnchor(id,slot,name);return new BMmPoint(checked(position.X+b.X-a.X),checked(position.Y+b.Y-a.Y),checked(position.Z+b.Z-a.Z));}
  internal bool TryGeometry(string source,string target,long actualTick,out JObject frame){frame=null;BuffWire.Need(actualTick==tick,"b_spatial_stale_tick");if(!roster.Entities.ContainsKey(source)||!roster.Entities.ContainsKey(target))throw new ArgumentException("b_spatial_unknown_entity");if(roster.Entities[source].Kind=="LOCAL_ENEMY"&&!states.ContainsKey(source)||roster.Entities[target].Kind=="LOCAL_ENEMY"&&!states.ContainsKey(target))return false;var a=ReferencePoint(source,"fireMm");var b=ReferencePoint(target,"hitMm");long range=roster.Entities[source].Kind=="LOCAL_ENEMY"?(roster.Entities[source].Definition=="enemy_spike_cart_gunner"?24000:1800):roster.Entities[source].Definition=="op_kyle"?1800:1000000000;if(input?.SchemaVersion==BDirectAttackInput.NamedLocalInputVersion&&roster.Entities[source].Kind=="OPERATOR"){if(!input.TryGetGeometry(source,target,out var suppliedRange))return false;range=(long)suppliedRange["maximumDistanceMm"];}bool los=geometry.Los(a,b);frame=new JObject{["sourceId"]=source,["targetId"]=target,["sourceSlot"]=Slot(source),["targetSlot"]=Slot(target),["distanceMm"]=BMmPoint.Distance(a,b),["maximumDistanceMm"]=range,["observedTick"]=tick,["validUntilTick"]=tick,["eligible"]=los&&BMmPoint.Squared(a,b)<=(System.Numerics.BigInteger)range*range,["lineOfSight"]=los,["geometryHash"]=geometry.Hash,["geometryVersion"]=geometry.Version,["revision"]=revision,["sourceGeneration"]=states.TryGetValue(source,out var s)?s.Generation:operators[source].Generation,["targetGeneration"]=states.TryGetValue(target,out var t)?t.Generation:operators[target].Generation,["sourcePointMm"]=a.Capture(),["targetPointMm"]=b.Capture()};return true;}
  JObject WithInstance(JObject row,int slot){foreach(var p in geometry.InstanceMetadata(slot).Properties())row[p.Name]=p.Value.DeepClone();return row;}
  internal JObject Capture()=>new JObject{["geometryHash"]=geometry.Hash,["definitionHash"]=geometry.DefinitionHash,["instances"]=geometry.Capture(),["tick"]=tick,["revision"]=revision,["sourceStatus"]=geometry.SourceStatus,["operatorMovementSource"]=geometry.OperatorMovementSource,["operators"]=new JArray(operators.Values.OrderBy(p=>p.Id,StringComparer.Ordinal).Select(p=>new JObject{["id"]=p.Id,["slot"]=p.Slot,["positionMm"]=p.Position.Capture(),["generation"]=p.Generation,["movementRevision"]=p.Revision,["startedTick"]=p.Started,["pathMm"]=p.Path==null?new JArray():new JArray(p.Path.Select(x=>x.Capture()))})),["positions"]=new JArray(states.Values.OrderBy(s=>s.Id,StringComparer.Ordinal).Select(s=>WithInstance(new JObject{["id"]=s.Id,["generation"]=s.Generation,["slot"]=s.Slot,["carriageInstanceId"]=roster.CarriageIds[s.Slot],["instanceGeneration"]=1,["phase"]=s.Phase,["positionMm"]=s.Position.Capture(),["targetId"]=s.Target==null?JValue.CreateNull():new JValue(s.Target),["ready"]=s.Ready,["pathRevision"]=s.PathRevision,["repathDestinationSlot"]=s.RepathSlot,["pathStartedTick"]=s.Started,["routeMm"]=s.Route==null?new JArray():new JArray(s.Route.Select(p=>p.Capture()))},s.Slot)))};
 }
}
